func TestEntityTools_GetEntityReturnsForkLocalMaterializedRevision(t *testing.T) {
	actor := models.AgentConfig{ExecutionMode: "live", ID: "tester", Type: "internal", Role: "operator", Tools: []string{"get_entity"}}
	bundle := loadWave1EntityToolBundle(t, actor, "review", "accounts", "", `
accounts:
  status: text
`)
	_, db, _ := testutil.StartPostgres(t)
	pg := storetest.AdmitPostgresRuntimeStore(t, db)
	sourceRunID := uuid.NewString()
	entityID := uuid.NewString()
	stateEventID := uuid.NewString()
	forkEventID := uuid.NewString()
	at := time.Unix(1700000710, 0).UTC()
	forkAt := at.Add(30 * time.Second)
	ctx := unmanagedToolTestContext()
	if _, err := pg.EnsureSourceArtifact(ctx, bundle.SourceArtifact); err != nil {
		t.Fatalf("EnsureSourceArtifact: %v", err)
	}
	bundleHash := bundle.SourceArtifact.BundleHash()
	storetest.RequireDurableDataCatalog(t, ctx, pg, bundleHash)
	storetest.RequireRun(t, ctx, pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: sourceRunID, StartedAt: at.Add(-time.Minute), BundleHash: bundleHash})
	storetest.InsertNativeCanonicalEventRecord(t, ctx, pg, eventtest.PersistedProjectionForProducer(stateEventID, "fork.state_entry", eventtest.Producer(events.EventProducerPlatform, "test"), "", []byte(`{}`), 0, sourceRunID, "", events.EventEnvelope{EntityID: entityID, Scope: events.EventScopeEntity}, at))
	if _, err := db.ExecContext(ctx, `
		INSERT INTO entity_mutations (
			run_id, entity_id, domain, path, old_value, new_value, caused_by_event, writer_type, writer_id, handler_step, created_at
		)
		VALUES
			($1::uuid, $2::uuid, 'lifecycle_state', '', 'null'::jsonb, '"queued"'::jsonb, $3::uuid, 'platform', 'revision-test', 'seed', $4),
			($1::uuid, $2::uuid, 'authored_field', 'status', 'null'::jsonb, '"open"'::jsonb, $3::uuid, 'platform', 'revision-test', 'seed', $4)
	`, sourceRunID, entityID, stateEventID, at); err != nil {
		t.Fatalf("seed mutations: %v", err)
	}
	if _, err := db.ExecContext(ctx, `
		INSERT INTO entity_state (
			run_id, entity_id, flow_instance, entity_type, current_state,
			gates, fields, accumulator, revision, entered_state_at, created_at, updated_at
		)
		VALUES (
			$1::uuid, $2::uuid, 'review/inst-1', 'accounts', 'queued',
			'{}'::jsonb, '{"status":"open"}'::jsonb, '{}'::jsonb, 1, $3, $3, $3
		)
	`, sourceRunID, entityID, at); err != nil {
		t.Fatalf("seed source entity_state: %v", err)
	}
	captureEntityToolRunForkRevision(t, db, sourceRunID)
	storetest.InsertNativeCanonicalEventRecord(t, ctx, pg, eventtest.PersistedProjectionForProducer(forkEventID, "fork.field_only", eventtest.Producer(events.EventProducerPlatform, "test"), "", []byte(`{}`), 0, sourceRunID, "", events.EventEnvelope{EntityID: entityID, Scope: events.EventScopeEntity}, forkAt))
	if _, err := db.ExecContext(ctx, `
		UPDATE entity_state
		SET current_state = 'done', fields = '{"status":"closed"}'::jsonb, revision = 7, updated_at = $3
		WHERE run_id = $1::uuid AND entity_id = $2::uuid
	`, sourceRunID, entityID, at.Add(time.Minute)); err != nil {
		t.Fatalf("advance live source entity_state: %v", err)
	}
	captureEntityToolRunForkRevision(t, db, sourceRunID)
	result, err := pg.MaterializeRunFork(ctx, runfork.RunForkMaterializeRequest{SourceRunID: sourceRunID, At: forkEventID})
	if err != nil {
		t.Fatalf("MaterializeRunFork: %v", err)
	}
	exec := runtimetools.NewExecutorWithOptions(nil, runtimetools.ExecutorOptions{EntityStore: pg, WorkflowSource: semanticview.Wrap(bundle), AllowInternalLegacyEntityTools: true})
	forkCtx := runtimetools.WithActor(runtimecorrelation.WithRunID(unmanagedToolTestContext(), result.ForkRunID), actor)
	out, err := exec.Execute(forkCtx, "get_entity", map[string]any{"entity_id": entityID})
	if err != nil {
		t.Fatalf("get_entity fork entity: %v", err)
	}
	entity, ok := out.(map[string]any)
	if !ok {
		t.Fatalf("expected entity map, got %#v", out)
	}
	if got := int(testNumericValue(entity["revision"])); got != 1 {
		t.Fatalf("fork get_entity revision = %d, want fork-local revision 1", got)
	}
	fields, ok := entity["fields"].(map[string]any)
	if !ok || strings.TrimSpace(asString(fields["status"])) != "open" {
		t.Fatalf("fork get_entity fields = %#v, want status=open", entity["fields"])
	}
	if got := strings.TrimSpace(asString(entity["current_state"])); got != "queued" {
		t.Fatalf("fork get_entity current_state = %q, want queued", got)
	}
	enteredStateAt, err := time.Parse(time.RFC3339Nano, strings.TrimSpace(asString(entity["entered_state_at"])))
	if err != nil {
		t.Fatalf("parse fork get_entity entered_state_at %q: %v", entity["entered_state_at"], err)
	}
	if !enteredStateAt.Equal(at) {
		t.Fatalf("fork get_entity entered_state_at = %s, want state-entry timestamp %s", enteredStateAt, at)
	}
}

