func TestAskHumanCreatesTypedCardAndContinuationForImportedAgentOnBothStores(t *testing.T) {
	for _, tc := range []struct {
		name  string
		store humanTaskToolStore
	}{{name: "postgres", store: newPostgresHumanTaskToolStoreForTest(t)}, {name: "sqlite", store: newSQLiteRuntimeToolStoreForTest(t)}} {
		t.Run(tc.name, func(t *testing.T) {
			const flowPath = "gateway/provider"
			cfg := &config.Config{Extensions: map[string]any{"budget": map[string]any{"human_tasks": map[string]any{"max_tasks_per_week": 3, "budget_reset": "monday", "auto_expire_hours": 48}}}}
			requester := models.AgentConfig{ExecutionMode: "live", ID: "requester", Role: "worker", FlowID: flowPath, FlowPath: flowPath, Tools: []string{"ask_human"}, Permissions: []string{"ask_human"}}
			source := humanTaskImportedSource(t, requester)
			declarations := semanticview.AgentDeclarations(source)
			if len(declarations) != 1 {
				t.Fatalf("requester declarations = %#v, want one", declarations)
			}
			plan, err := semanticview.ScopedAgentNamePlan(source, declarations[0])
			if err != nil {
				t.Fatalf("requester declaration name: %v", err)
			}
			requester.Identity = agentidentitytest.Declared(t, plan.AgentID, plan.OwnerURI, flowPath, "provider", flowPath)
			ctx, replyContextID, sourceEventID := seedReplyToolContext(t, tc.store)
			ctx = runtimeeffects.WithLogicalOperationIdentity(ctx, "provider-turn")
			ctx = runtimeeffects.WithLogicalOperationIdentitySegment(ctx, "tool_call:1:0:mock-1:ask_human")
			logicalCall, ok := runtimeeffects.LogicalOperationIdentityFromContext(ctx)
			if !ok || logicalCall != "provider-turn\x00tool_call:1:0:mock-1:ask_human" {
				t.Fatalf("logical call = %q, present %v", logicalCall, ok)
			}
			ctx = runtimecorrelation.WithSourceArtifactFact(ctx, authorActivityTestSourceArtifactFact)
			requester, loader := humanTaskConstructedRequester(t, ctx, tc.store, source, requester)
			exec := runtimetools.NewExecutorWithOptions(nil, runtimetools.ExecutorOptions{Config: cfg, HumanTaskStore: tc.store, AuthorityProvider: allowHumanTaskAuthority{}, WorkflowSource: source, WorkflowInstances: loader})
			ctx = runtimetools.WithActor(ctx, requester)
			input := map[string]any{"scope": "flow", "category": "review", "description": "Review provider response", "talking_points": []string{"Check source evidence"}, "expected_value": "approval", "priority": "high"}
			created, err := exec.Execute(ctx, "ask_human", input)
			if err != nil {
				t.Fatalf("ask_human: %v", err)
			}
			cardID := strings.TrimSpace(asString(created.(map[string]any)["card_id"]))
			card, err := tc.store.GetDecisionCard(context.Background(), cardID)
			if err != nil {
				t.Fatalf("GetDecisionCard: %v", err)
			}
			anchor, err := card.Anchor.HumanTask()
			if err != nil {
				t.Fatal(err)
			}
			operation, err := decisioncard.NewHumanTaskOperationID(runtimecorrelation.RunIDFromContext(ctx), logicalCall)
			if err != nil {
				t.Fatal(err)
			}
			if anchor.RequesterAgentID != requester.ID || anchor.OperationID != operation || anchor.Scope.Kind != decisioncard.ScopeFlow || anchor.Scope.FlowInstance != flowPath {
				t.Fatalf("human-task anchor = %#v", anchor)
			}
			if got, ok := runtimeeffects.LogicalOperationIdentityFromContext(ctx); !ok || got != logicalCall {
				t.Fatalf("ask_human changed the internal logical call: %q", got)
			}
			provenance, ok := card.Provenance.ObjectMap()
			if !ok {
				t.Fatal("persisted provenance is not an object")
			}
			if got, _ := provenance["logical_operation_id"].String(); got != operation.String() || strings.ContainsRune(got, '\x00') {
				t.Fatalf("persisted operation = %q, want %q", got, operation.String())
			}
			wantSourceRoute := events.RouteIdentity{FlowID: flowPath, FlowInstance: flowPath, EntityID: requester.EntityID}
			if got := anchor.Source.Route().Normalized(); got != wantSourceRoute {
				t.Fatalf("human-task routing source = %#v, want %#v", got, wantSourceRoute)
			}
			continuation, err := tc.store.LoadHumanTaskContinuation(context.Background(), cardID)
			if err != nil {
				t.Fatalf("LoadHumanTaskContinuation: %v", err)
			}
			if continuation.ReplyContextID != replyContextID || continuation.SourceEventID != sourceEventID || continuation.State != decisioncard.HumanTaskContinuationPending {
				t.Fatalf("human-task continuation = %#v", continuation)
			}
			if got := continuation.RequesterRoute.Normalized(); got != (events.RouteIdentity{FlowID: flowPath, FlowInstance: flowPath, EntityID: requester.EntityID}) {
				t.Fatalf("human-task requester route = %#v", got)
			}
			if got := continuation.DeadlineAt.Sub(card.CreatedAt); got != 48*time.Hour {
				t.Fatalf("default expiry = %s, want 48h", got)
			}
			replayed, err := exec.Execute(ctx, "ask_human", input)
			if err != nil || strings.TrimSpace(asString(replayed.(map[string]any)["card_id"])) != cardID {
				t.Fatalf("idempotent replay = %#v, %v", replayed, err)
			}
			changed := map[string]any{}
			for key, value := range input {
				changed[key] = value
			}
			changed["description"] = "Changed request under the same operation"
			if _, err := exec.Execute(ctx, "ask_human", changed); err == nil {
				t.Fatal("changed content under the same operation identity was accepted")
			}
			forkCtx, _, _ := seedReplyToolContext(t, tc.store)
			forkCtx = runtimeeffects.WithLogicalOperationIdentity(forkCtx, logicalCall)
			forkCtx = runtimecorrelation.WithSourceArtifactFact(forkCtx, authorActivityTestSourceArtifactFact)
			forkRequester, _ := humanTaskConstructedRequester(t, forkCtx, tc.store, source, requester)
			forkCtx = runtimetools.WithActor(forkCtx, forkRequester)
			forked, err := exec.Execute(forkCtx, "ask_human", input)
			if err != nil {
				t.Fatalf("fork-local ask_human: %v", err)
			}
			if forkedCardID := strings.TrimSpace(asString(forked.(map[string]any)["card_id"])); forkedCardID == "" || forkedCardID == cardID {
				t.Fatalf("fork-local card id = %q, source card id = %q", forkedCardID, cardID)
			}
		})
	}
}

